'use strict';
const SinglePlan={
 fields:{invoice_no:'发票号',packing_list_no:'装箱单号',export_license_no:'出口许可证号',transporter:'运输商',destination:'目的地',vehicle_no:'车牌号',planned_load_date:'计划装车日期'},
 can(){return Business.can('loading-plan:write');},
 status(d){if(d.status==='CANCELLED')return 'CANCELLED';return d.entry_type==='DRAFT'||d.status==='WAITING'&&!d.batch_count&&!d.direct_entry?'DRAFT':d.status;},
 row(d){const draft=d.entry_type==='DRAFT',status=this.status(d),base=draft?'/loading-plans/'+d.id:'/loading-plans/orders/'+d.id,edit=base+'/edit',cancel=base+'/cancel';return `<tr data-single-plan="${d.id}"><td><a data-no-i18n href="${base}">${esc(d.code)}</a></td><td data-no-i18n>${esc(d.invoice_no||'—')}<br>${esc(d.packing_list_no||'—')}</td><td data-no-i18n>${esc(d.customer_name)}<br>${esc(d.contract_no||'—')}</td><td data-no-i18n>${esc(d.vehicle_no||'—')}</td><td data-no-i18n>${esc(d.shipment_batch_no||'—')}</td><td data-no-i18n>${esc(d.planned_load_date?.slice(0,10)||'—')}</td><td>${status==='DRAFT'?'<span class="lp-badge lp-WAITING">待补全</span>':LoadingPlans.badge(status)}</td><td><div class="plan-row-actions"><a class="button secondary" href="${base}">查看</a>${this.can()&&!['OUTBOUND','CANCELLED'].includes(status)?`<a class="button secondary" href="${edit}">${status==='DRAFT'?'补全 / 编辑':'编辑'}</a><a class="button secondary" href="${cancel}">取消</a>`:''}${!draft&&status==='WAITING'&&Business.can('loading-plan:match')&&Business.can('load:write')?`<a class="button primary" href="/outbounds/loads/new?document_id=${d.id}">创建装车单</a>`:''}${d.loading_id?`<a class="button secondary" href="/outbounds/loads/${d.loading_id}">查看装车单</a>`:''}</div></td></tr>`;},
 async list(){const q=new URLSearchParams(location.search);q.delete('tab');const {items}=await API.request('/loading-plans/unified?'+q);Router.page('装车计划单',`<div class="business-toolbar">${this.can()?'<a class="button primary" href="/loading-plans/new">新建装车计划</a>':''}</div><p class="plan-workflow-help">一张装车计划单对应一辆车。填写发票、运输、车牌、批次和装车日期后即可用于装车，无需重复创建。</p><form id="single-plan-search" class="shipping-filters"><label>计划单号 / 发票号 / 装箱单号 / 车牌<input name="search" maxlength="160" value="${esc(q.get('search')||'')}"></label><label>状态<select name="status"><option value="">全部状态</option>${Object.entries({DRAFT:'待补全',...LoadingPlans.states}).map(([k,v])=>`<option value="${k}" ${q.get('status')===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="button secondary">查询</button></form><div class="business-table"><table><thead><tr><th>装车计划单号</th><th>发票号 / 装箱单号</th><th>客户 / 合同</th><th>车牌号</th><th>批次号</th><th>计划装车日期</th><th>状态</th><th>操作</th></tr></thead><tbody>${items.map(d=>this.row(d)).join('')||'<tr><td colspan="8">暂无装车计划单</td></tr>'}</tbody></table></div>`);$('single-plan-search').onsubmit=e=>{e.preventDefault();Router.go('/loading-plans?'+new URLSearchParams(new FormData(e.target)));};},
 async form(id,legacyGroup){let d=id?await API.request('/loading-plans/unified/documents/'+id):null,g;if(legacyGroup){const data=await API.request('/loading-plans/'+legacyGroup);g=data.group;if(data.documents.length){if(data.documents.length===1){
    const document=data.documents[0],locked=['OUTBOUND','CANCELLED'].includes(document.status),next='/loading-plans/orders/'+document.id+(locked?'':'/edit');
    history.replaceState(history.state,'',next+location.search+location.hash);Router.current=next;
    return locked?this.detail(document.id):this.form(document.id);
   }return this.legacyChoices(g,data.documents);}}if(d&&['OUTBOUND','CANCELLED'].includes(d.status)||g?.cancelled_at)throw Error('计划单已锁定或取消');const current=d||g||{},plans=(await API.request('/plans')).items,planId=current.sales_plan_id||new URLSearchParams(location.search).get('sales_plan_id')||'',existingLots=d?.lots||[];
 Router.page(id?'编辑装车计划单':'新建装车计划单',`<form id="single-plan-form" class="user-form"><label>关联销售计划<select name="sales_plan_id" required ${planId?'disabled':''}><option value="">请选择销售计划</option>${plans.filter(p=>(p.status==='OPEN'||p.id===planId)&&!['PENDING','REJECTED'].includes(p.approval_state)).map(p=>`<option value="${p.id}" ${p.id===planId?'selected':''}>${esc(p.code+' · '+p.customer_name+' · '+(p.contract_no||'—'))}</option>`).join('')}</select></label><div id="single-plan-context"></div><div class="form-grid">${Object.entries(this.fields).map(([key,label])=>`<label>${label}<input name="${key}" type="${key==='planned_load_date'?'date':'text'}" value="${esc(key==='packing_list_no'?(current.invoice_no?current.invoice_no+'-PL':''):(current[key]||'').slice(0,key==='planned_load_date'?10:1000))}" maxlength="${key==='invoice_no'?77:key==='packing_list_no'||key==='vehicle_no'?80:key==='destination'?1000:160}" ${key==='packing_list_no'?'readonly':''} ${['invoice_no','vehicle_no','planned_load_date'].includes(key)?'required':''}></label>`).join('')}</div><label>批次号（单选，整批锁定）<select id="single-plan-lots" name="allocation_ids" size="5" required></select></label><p id="single-plan-lot-note">请先选择销售计划。</p><p>装箱单号自动生成为“发票号-PL”，不可手工填写。</p><p class="error" id="single-plan-error" role="alert"></p><button class="button primary" type="submit">保存装车计划单</button></form>`);const form=$('single-plan-form');form.operationPlans=plans;form.operationRecord=current;form.elements.invoice_no.oninput=()=>form.elements.packing_list_no.value=form.elements.invoice_no.value.trim()?form.elements.invoice_no.value.trim()+'-PL':'';let sequence=0;const loadLots=async()=>{const seq=++sequence,plan=form.elements.sales_plan_id.value,p=plans.find(p=>p.id===plan);$('single-plan-context').innerHTML=p?LoadingPlans.context({...p,sales_plan_code:p.code}):'';$('single-plan-lots').replaceChildren();if(!plan)return;try{const {items}=await API.request('/loading-plans/unified/lots?sales_plan_id='+plan+(id?'&document_id='+id:''));if(seq!==sequence)return;$('single-plan-lots').innerHTML=items.map(a=>`<option value="${a.id}" ${existingLots.some(x=>x.id===a.id)?'selected':''}>${esc(a.lot_no+' · '+(V261.states[a.workflow_state]||a.workflow_state)+' · '+a.bundle_count+' 捆')}</option>`).join('');$('single-plan-lot-note').textContent=items.length?'装车时自动带出所选批次的可用捆包。':'同客户、同合同下暂无已完成的可用备货批次。';}catch(err){$('single-plan-error').textContent=err.message;}};form.elements.sales_plan_id.onchange=loadLots;await loadLots();form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(form));b.sales_plan_id=form.elements.sales_plan_id.value;b.allocation_ids=[...$('single-plan-lots').selectedOptions].map(o=>o.value);if(id)b.version=d.version;if(g){b.legacy_group_id=g.id;b.group_version=g.version;}const saved=await API.request('/loading-plans/unified'+(id?'/documents/'+id:''),{method:id?'PATCH':'POST',body:b});await Router.go('/loading-plans/orders/'+saved.id);}catch(err){$('single-plan-error').textContent=err.message;e.submitter.disabled=false;}};
 },
 legacyChoices(group,documents){
  const en=I18n.language==='en',links=documents.map(d=>{
   const edit=this.can()&&!['OUTBOUND','CANCELLED'].includes(d.status);
   return '<li><a class="button secondary" href="/loading-plans/orders/'+esc(d.id)+(edit?'/edit':'')+'" data-no-i18n>'+esc(d.invoice_no||d.code)+'</a></li>';
  });
  Router.page(en?'Select a Loading Plan':'选择装车计划单',LoadingPlans.context(group)+'<ul id="legacy-plan-documents">'+links.join('')+'</ul>');
 },
 async detail(id){const d=await API.request('/loading-plans/unified/documents/'+id),editable=this.can()&&!['OUTBOUND','CANCELLED'].includes(d.status),ready=d.status==='WAITING'&&d.lots.length;Router.page('装车计划 · '+(d.invoice_no||d.code),LoadingPlans.context(d)+`<div class="business-toolbar">${d.status==='WAITING'&&!d.lots.length?'<span class="lp-badge lp-WAITING">待补全</span>':LoadingPlans.badge(d.status)}${editable?`<a class="button secondary" href="/loading-plans/orders/${id}/edit">编辑</a><a class="button secondary" href="/loading-plans/orders/${id}/cancel">取消</a>`:''}${ready&&Business.can('loading-plan:match')&&Business.can('load:write')?`<a class="button primary" href="/outbounds/loads/new?document_id=${id}">创建装车单</a>`:''}${d.loading_id?`<a class="button primary" href="/outbounds/loads/${d.loading_id}">查看装车单</a>`:''}<a class="button secondary" href="/loading-plans/query">返回列表</a></div><dl class="lp-fields loading-plan-facts">${Object.entries(this.fields).map(([key,label])=>`<dt>${label}</dt><dd data-no-i18n>${esc(d[key]?.slice(0,key==='planned_load_date'?10:1000)||'—')}</dd>`).join('')}<dt>批次号</dt><dd data-no-i18n>${esc(d.lots.map(a=>a.lot_no).join(' / ')||d.shipment_batch_no||'待补全')}</dd></dl>${!d.lots.length&&editable?'<p class="dialog-notice">请编辑并关联备货批次，完成后即可创建装车单。</p>':''}`);},
 async resolve(group){const data=await API.request('/loading-plans/'+group);if(data.documents.length===1)return this.detail(data.documents[0].id);if(data.documents.length>1)return this.list();const g=data.group;Router.page(g.cancelled_at?'装车计划单 · 已取消':'装车计划单 · 待补全',LoadingPlans.context(g)+`<p>${g.cancelled_at?'计划单已取消。':'此记录为原有未完成计划，补齐车牌、批次和装车日期后即可使用，无需另建车辆计划单。'}</p><div class="business-toolbar">${this.can()&&!g.cancelled_at?`<a class="button primary" href="/loading-plans/${g.id}/edit">补全 / 编辑</a><a class="button secondary" href="/loading-plans/${g.id}/cancel">取消</a>`:''}<a class="button secondary" href="/loading-plans">返回列表</a></div>`);},
 async cancel(id){const d=await API.request('/loading-plans/unified/documents/'+id);if(!this.can())throw Error('没有维护装车计划的权限');Router.page('取消装车计划单',LoadingPlans.context(d)+(d.loading_id?`<p class="dialog-notice">${d.status==='OUTBOUND'?'计划单已正式出库，不能取消。':'请先解除已关联装车单的匹配，再取消计划单。'}</p><a class="button secondary" href="/outbounds/loads/${d.loading_id}">查看装车单</a>`:d.cancelled_at?'<p>计划单已取消。</p>':`<form id="lp-cancel-form" class="user-form"><label>取消原因<input name="reason" required maxlength="1000"></label><button class="button primary">确认取消</button><p id="lp-cancel-error" class="error" role="alert"></p></form>`));LoadingPlans.bindCancel('/loading-plan-documents/'+id,d.version,()=>Router.go('/loading-plans'));},
 async help(id){const form=$('lp-load-form'),select=$('lp-match-select');if(!form||!select)return;const q=new URLSearchParams(location.search);const helper=document.createElement('section');helper.id='lp-match-help';helper.className='plan-match-help';helper.innerHTML=select.options.length>1?'<p>选择装车计划单后自动带出指定批次，勾选本车实际装载的捆包并提交审核。</p>':'<p>暂无符合条件的待匹配装车计划单，请先完成装车计划。</p>'+(this.can()?'<a class="button secondary" href="/loading-plans/new">新建装车计划</a>':'');select.closest('label').after(helper);if(q.get('document_id')&&!select.value){try{const d=await API.request('/loading-plans/unified/documents/'+q.get('document_id'));helper.innerHTML='<p>'+(!d.lots.length?'计划单尚未关联备货批次，请先编辑补全。':'计划单已匹配或取消，不能重复匹配。')+'</p><a class="button secondary" href="/loading-plans/orders/'+d.id+'">查看计划单</a>';}catch(err){helper.textContent=err.message;}}const show=async()=>{if(!select.value)return;try{const d=await API.request('/loading-plans/unified/documents/'+select.value);const pending=d.lots.filter(x=>!['PREPARED','PARTIAL'].includes(x.workflow_state));helper.innerHTML=(pending.length?'<p class="dialog-notice">指定批次尚未完成备货审核：<span data-no-i18n>'+esc(pending.map(x=>x.lot_no).join(' / '))+'</span></p>':'')+'<p>计划指定批次：<strong data-no-i18n>'+esc(d.lots.map(x=>x.lot_no).join(' / ')||d.shipment_batch_no||'待补全')+'</strong></p><p>下方仅显示对应批次的可用捆包，勾选本车装载捆包后提交审核。</p>';}catch(err){helper.textContent=err.message;}};select.addEventListener('change',show);await show();}
};
LoadingPlans.list=SinglePlan.list.bind(SinglePlan);LoadingPlans.groupForm=id=>SinglePlan.form(null,id);LoadingPlans.docForm=(group,id)=>SinglePlan.form(id,group);LoadingPlans.doc=SinglePlan.detail.bind(SinglePlan);LoadingPlans.group=SinglePlan.resolve.bind(SinglePlan);PlanAccess.matchingHelp=SinglePlan.help.bind(SinglePlan);
const singlePermission=Router.permission.bind(Router);Router.permission=path=>path.startsWith('/loading-plans/')&&/\/cancel$/.test(path)?'loading-plan:write':singlePermission(path);
const singleInit=Router.init.bind(Router);Router.init=async function(){this.add(/^\/loading-plans\/orders\/([0-9a-f-]{36})\/cancel$/,id=>SinglePlan.cancel(id));return singleInit();};

PlanAccess.cancel=async function(group){const data=await API.request('/loading-plans/'+group);if(data.documents.length===1)return SinglePlan.cancel(data.documents[0].id);if(data.documents.length>1)return SinglePlan.list();const g=data.group;if(!SinglePlan.can())throw Error('没有维护装车计划的权限');Router.page('取消装车计划单',LoadingPlans.context(g)+(g.cancelled_at?'<p>计划单已取消。</p>':'<form id="lp-cancel-form" class="user-form"><label>取消原因<input name="reason" required maxlength="1000"></label><button class="button primary">确认取消</button><p id="lp-cancel-error" class="error" role="alert"></p></form>'));LoadingPlans.bindCancel('/loading-plans/'+g.id,g.version,()=>Router.go('/loading-plans'));};
